cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

// General fallback kernel (any floating dtype, any p): one block per row.
template <typename scalar_t>
__global__ void triplet_margin_loss_kernel(
    const scalar_t* __restrict__ anchor,
    const scalar_t* __restrict__ positive,
    const scalar_t* __restrict__ negative,
    scalar_t* __restrict__ out,
    const long D,
    const double margin,
    const double p,
    const double eps,
    const double inv_batch)
{
    __shared__ scalar_t s_pos[BLOCK_SIZE];
    __shared__ scalar_t s_neg[BLOCK_SIZE];

    const long row = blockIdx.x;
    const scalar_t* a   = anchor   + row * D;
    const scalar_t* pos = positive + row * D;
    const scalar_t* neg = negative + row * D;

    scalar_t sum_p = 0;
    scalar_t sum_n = 0;
    for (long i = threadIdx.x; i < D; i += BLOCK_SIZE) {
        double dp = (double)a[i] - (double)pos[i] + eps;
        double dn = (double)a[i] - (double)neg[i] + eps;
        if (p == 2.0) {
            sum_p += (scalar_t)(dp * dp);
            sum_n += (scalar_t)(dn * dn);
        } else {
            sum_p += (scalar_t)pow(fabs(dp), p);
            sum_n += (scalar_t)pow(fabs(dn), p);
        }
    }

    s_pos[threadIdx.x] = sum_p;
    s_neg[threadIdx.x] = sum_n;
    __syncthreads();

    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_pos[threadIdx.x] += s_pos[threadIdx.x + s];
            s_neg[threadIdx.x] += s_neg[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        double dist_pos = pow((double)s_pos[0], 1.0 / p);
        double dist_neg = pow((double)s_neg[0], 1.0 / p);
        double loss = margin + dist_pos - dist_neg;
        if (loss < 0.0) loss = 0.0;
        if (loss > 0.0) {
            atomicAdd(out, (scalar_t)(loss * inv_batch));
        }
    }
}

// Fast path: float, p == 2, vectorized with float4 loads.
__global__ void triplet_margin_loss_p2_vec4_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ out,
    const long D,
    const float margin,
    const float eps,
    const float inv_batch)
{
    __shared__ float s_pos[BLOCK_SIZE];
    __shared__ float s_neg[BLOCK_SIZE];

    const long row = blockIdx.x;
    const float* a   = anchor   + row * D;
    const float* pos = positive + row * D;
    const float* neg = negative + row * D;

    float sum_p0 = 0.0f, sum_p1 = 0.0f, sum_p2 = 0.0f, sum_p3 = 0.0f;
    float sum_n0 = 0.0f, sum_n1 = 0.0f, sum_n2 = 0.0f, sum_n3 = 0.0f;
    const long D4 = D >> 2;
    const float4* a4 = reinterpret_cast<const float4*>(a);
    const float4* p4 = reinterpret_cast<const float4*>(pos);
    const float4* n4 = reinterpret_cast<const float4*>(neg);
    // Unroll by 4 with independent accumulators and __ldg to expose more
    // memory-level parallelism on this bandwidth-bound reduction.
    long i = threadIdx.x;
    for (; i + 3 * BLOCK_SIZE < D4; i += 4 * BLOCK_SIZE) {
        float4 av0 = __ldg(a4 + i);
        float4 pv0 = __ldg(p4 + i);
        float4 nv0 = __ldg(n4 + i);
        float4 av1 = __ldg(a4 + i + BLOCK_SIZE);
        float4 pv1 = __ldg(p4 + i + BLOCK_SIZE);
        float4 nv1 = __ldg(n4 + i + BLOCK_SIZE);
        float4 av2 = __ldg(a4 + i + 2 * BLOCK_SIZE);
        float4 pv2 = __ldg(p4 + i + 2 * BLOCK_SIZE);
        float4 nv2 = __ldg(n4 + i + 2 * BLOCK_SIZE);
        float4 av3 = __ldg(a4 + i + 3 * BLOCK_SIZE);
        float4 pv3 = __ldg(p4 + i + 3 * BLOCK_SIZE);
        float4 nv3 = __ldg(n4 + i + 3 * BLOCK_SIZE);
        float dp, dn;
        dp = av0.x - pv0.x + eps; dn = av0.x - nv0.x + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av0.y - pv0.y + eps; dn = av0.y - nv0.y + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av0.z - pv0.z + eps; dn = av0.z - nv0.z + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av0.w - pv0.w + eps; dn = av0.w - nv0.w + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av1.x - pv1.x + eps; dn = av1.x - nv1.x + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
        dp = av1.y - pv1.y + eps; dn = av1.y - nv1.y + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
        dp = av1.z - pv1.z + eps; dn = av1.z - nv1.z + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
        dp = av1.w - pv1.w + eps; dn = av1.w - nv1.w + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
        dp = av2.x - pv2.x + eps; dn = av2.x - nv2.x + eps; sum_p2 += dp * dp; sum_n2 += dn * dn;
        dp = av2.y - pv2.y + eps; dn = av2.y - nv2.y + eps; sum_p2 += dp * dp; sum_n2 += dn * dn;
        dp = av2.z - pv2.z + eps; dn = av2.z - nv2.z + eps; sum_p2 += dp * dp; sum_n2 += dn * dn;
        dp = av2.w - pv2.w + eps; dn = av2.w - nv2.w + eps; sum_p2 += dp * dp; sum_n2 += dn * dn;
        dp = av3.x - pv3.x + eps; dn = av3.x - nv3.x + eps; sum_p3 += dp * dp; sum_n3 += dn * dn;
        dp = av3.y - pv3.y + eps; dn = av3.y - nv3.y + eps; sum_p3 += dp * dp; sum_n3 += dn * dn;
        dp = av3.z - pv3.z + eps; dn = av3.z - nv3.z + eps; sum_p3 += dp * dp; sum_n3 += dn * dn;
        dp = av3.w - pv3.w + eps; dn = av3.w - nv3.w + eps; sum_p3 += dp * dp; sum_n3 += dn * dn;
    }
    for (; i + BLOCK_SIZE < D4; i += 2 * BLOCK_SIZE) {
        float4 av0 = __ldg(a4 + i);
        float4 pv0 = __ldg(p4 + i);
        float4 nv0 = __ldg(n4 + i);
        float4 av1 = __ldg(a4 + i + BLOCK_SIZE);
        float4 pv1 = __ldg(p4 + i + BLOCK_SIZE);
        float4 nv1 = __ldg(n4 + i + BLOCK_SIZE);
        float dp, dn;
        dp = av0.x - pv0.x + eps; dn = av0.x - nv0.x + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av0.y - pv0.y + eps; dn = av0.y - nv0.y + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av0.z - pv0.z + eps; dn = av0.z - nv0.z + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av0.w - pv0.w + eps; dn = av0.w - nv0.w + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av1.x - pv1.x + eps; dn = av1.x - nv1.x + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
        dp = av1.y - pv1.y + eps; dn = av1.y - nv1.y + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
        dp = av1.z - pv1.z + eps; dn = av1.z - nv1.z + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
        dp = av1.w - pv1.w + eps; dn = av1.w - nv1.w + eps; sum_p1 += dp * dp; sum_n1 += dn * dn;
    }
    for (; i < D4; i += BLOCK_SIZE) {
        float4 av = __ldg(a4 + i);
        float4 pv = __ldg(p4 + i);
        float4 nv = __ldg(n4 + i);
        float dp, dn;
        dp = av.x - pv.x + eps; dn = av.x - nv.x + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av.y - pv.y + eps; dn = av.y - nv.y + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av.z - pv.z + eps; dn = av.z - nv.z + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
        dp = av.w - pv.w + eps; dn = av.w - nv.w + eps; sum_p0 += dp * dp; sum_n0 += dn * dn;
    }
    // Handle tail if D is not divisible by 4
    for (long t = (D4 << 2) + threadIdx.x; t < D; t += BLOCK_SIZE) {
        float dp = a[t] - pos[t] + eps;
        float dn = a[t] - neg[t] + eps;
        sum_p1 += dp * dp;
        sum_n1 += dn * dn;
    }
    float sum_p = (sum_p0 + sum_p1) + (sum_p2 + sum_p3);
    float sum_n = (sum_n0 + sum_n1) + (sum_n2 + sum_n3);

    s_pos[threadIdx.x] = sum_p;
    s_neg[threadIdx.x] = sum_n;
    __syncthreads();

    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_pos[threadIdx.x] += s_pos[threadIdx.x + s];
            s_neg[threadIdx.x] += s_neg[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float dist_pos = sqrtf(s_pos[0]);
        float dist_neg = sqrtf(s_neg[0]);
        float loss = margin + dist_pos - dist_neg;
        if (loss > 0.0f) {
            atomicAdd(out, loss * inv_batch);
        }
    }
}

torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative,
                                          double margin, double p, double eps)
{
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
                "All inputs must be CUDA tensors");
    TORCH_CHECK(anchor.dim() >= 1, "anchor must have at least 1 dimension");

    auto a   = anchor.contiguous();
    auto pos = positive.contiguous();
    auto neg = negative.contiguous();

    auto out = torch::zeros({}, a.options());

    const long B = a.size(0);
    const long D = (B > 0) ? (a.numel() / B) : 0;
    if (B == 0) {
        return out;
    }

    const double inv_batch = 1.0 / (double)B;
    dim3 grid((unsigned)B);
    dim3 block(BLOCK_SIZE);
    auto stream = at::cuda::getCurrentCUDAStream();

    if (a.scalar_type() == torch::kFloat && p == 2.0) {
        triplet_margin_loss_p2_vec4_kernel<<<grid, block, 0, stream>>>(
            a.data_ptr<float>(),
            pos.data_ptr<float>(),
            neg.data_ptr<float>(),
            out.data_ptr<float>(),
            D,
            (float)margin,
            (float)eps,
            (float)inv_batch);
    } else {
        AT_DISPATCH_FLOATING_TYPES(a.scalar_type(), "triplet_margin_loss_forward", [&] {
            triplet_margin_loss_kernel<scalar_t><<<grid, block, 0, stream>>>(
                a.data_ptr<scalar_t>(),
                pos.data_ptr<scalar_t>(),
                neg.data_ptr<scalar_t>(),
                out.data_ptr<scalar_t>(),
                D,
                margin,
                p,
                eps,
                inv_batch);
        });
    }

    return out;
}
"""

_module = load_inline(
    name="triplet_margin_loss_cuda",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["triplet_margin_loss_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Triplet Margin Loss implemented with a single fused custom CUDA kernel.

    Matches torch.nn.TripletMarginLoss defaults: p=2.0, eps=1e-6, swap=False,
    reduction='mean'.
